function r(e){return new Intl.NumberFormat("vi-VN",{style:"currency",currency:"VND",minimumFractionDigits:0}).format(e).replace("₫","₫").trim()}function a(e){if(!e)return"--/--/----";const t=new Date(e);return isNaN(t.getTime())?"--/--/----":new Intl.DateTimeFormat("vi-VN",{day:"2-digit",month:"2-digit",year:"numeric"}).format(t)}function i(e){if(!e)return"--/--/---- --:--";const t=new Date(e);return isNaN(t.getTime())?"--/--/---- --:--":new Intl.DateTimeFormat("vi-VN",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit"}).format(t)}function n(e){return new Intl.NumberFormat("vi-VN").format(e)}function m(e){if(!e)return"";let t=e.replace(/([A-Z]+)([A-Z][a-z])/g,"$1 $2");return t=t.replace(/([a-z\d])([A-Z])/g,"$1 $2"),t=t.replace(/([a-zA-Z]{2,})(\d)/g,"$1 $2"),t=t.replace(/(\d)([a-zA-Z]{2,})/g,"$1 $2"),t.replace(/\s+/g," ").trim()}export{m as a,a as b,i as c,n as d,r as f};
